theorem extracted_1.{u_5, u_2, u_1} {Ω : Type u_1} {Ω' : Type u_2} {G : Type u_5} [mΩ : MeasurableSpace Ω]
  {μ : Measure Ω} [mΩ' : MeasurableSpace Ω'] {μ' : Measure Ω'} [hG : MeasurableSpace G] {X : Ω → G} {Y : Ω' → G}
  [inst : Fintype G] [inst_1 : MeasurableSingletonClass G] [inst_2 : IsProbabilityMeasure μ]
  [inst_3 : IsProbabilityMeasure μ'] (hX : Measurable X) (hY : Measurable Y)
  (habs : ∀ (x : G), (Measure.map Y μ') {x} = 0 → (Measure.map X μ) {x} = 0) (h : KL[X ; μ # Y ; μ'] = 0) :
  let νY := Measure.map Y μ';
  IsProbabilityMeasure νY →
    let νX := Measure.map X μ;
    IsProbabilityMeasure νX → ∃ r, ∀ x ∈ Finset.univ, (νX {x}).toReal = r * (νY {x}).toReal := sorry

